        const showSelected=contact=>{content.querySelector('.fm-phone-selected')?.remove();number.hidden=!!contact;pad.hidden=!!contact;matches.hidden=!!contact;matches.replaceChildren();start.hidden=false;if(!contact)return;const selected=document.createElement('div');selected.className='fm-phone-selected';selected.innerHTML=`<span><strong>${esc(contact.name)}</strong><small>${esc(formatPhone(contact.phone))}</small></span><button type="button" aria-label="Remove selected contact" title="Remove selected contact">${icon('xmark')}</button>`;content.prepend(selected);selected.querySelector('button').onclick=()=>{field.value='';delete state.prepared.contact_id;delete state.prepared.project_id;delete state.prepared.customer_name;delete state.prepared.customer_number;showSelected(null);field.focus();};};
